        protected override void BeforeRun()
        {
            // If all works correctly you should not really see this :-)
            Console.WriteLine("Cosmos booted successfully. Let's go in Graphical Mode");

            /*
            You don't have to specify the Mode, but here we do to show that you can.
            To not specify the Mode and pick the best one, use:
            canvas = FullScreenCanvas.GetFullScreenCanvas();
            */
            canvas = FullScreenCanvas.GetFullScreenCanvas(new Mode(1920, 1080, ColorDepth.ColorDepth32));

            // This will clear the canvas with the specified color.
            canvas.Clear(Color.Black);
        }

        protected override void Run()
        {
            try
            {
                DrawACSIIString(canvas, Color.LimeGreen, "S'.O.S.", 750, 150, 8);
                DrawACSIIString(canvas, Color.LimeGreen, "Choose an option [1..3]", 65, 400, 3);
                DrawACSIIString(canvas, Color.LimeGreen, "1. Open Menu", 65, 500, 3);
                DrawACSIIString(canvas, Color.LimeGreen, "2. Shutdown", 65, 600, 3);
                DrawACSIIString(canvas, Color.LimeGreen, "3. Reboot", 65, 700, 3);
                canvas.Display();

                string opcio = Console.ReadLine();
                if (opcio == "1")
                {
                    Mostramenu();
                }
                else if (opcio == "2")
                {
                    Sys.Power.Shutdown();
                }
                else if (opcio == "3")
                {
                    Sys.Power.Reboot();
                }



            }
            catch (Exception e)
            {
                Console.WriteLine(e.ToString());
            }
        }
        void Mostramenu()
        {
            canvas.Clear();
            DrawACSIIString(canvas, Color.LimeGreen, "Help", 25, 215, 2);
            DrawACSIIString(canvas, Color.LimeGreen, "About", 25, 245, 2);
            DrawACSIIString(canvas, Color.LimeGreen, "File Management", 25, 275, 2);

            canvas.Display();
            string opcioMenu = Console.ReadLine();
            
            if (opcioMenu == "help")
            {
                Help();
            }
            else if (opcioMenu == "about")
